import { CardElement, useStripe, useElements } from "@stripe/react-stripe-js";
import { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import axios from "axios";
import { ethers } from "ethers";

const API_BASE_URL = "http://localhost:5001/api/payment";

const cardStyle = {
  style: {
    base: {
      color: "#ffffff",
      fontSize: "16px",
      "::placeholder": { color: "#aab7c4" },
    },
    invalid: { color: "#ff0033" },
  },
};

const PaymentForm = () => {
  const stripe = useStripe();
  const elements = useElements();
  const navigate = useNavigate();
  const location = useLocation();

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [clientWallet, setClientWallet] = useState(null);

  const [amount, setAmount] = useState("");
  const [currency, setCurrency] = useState("usd");
  const [type, setType] = useState("full");
  const [method, setMethod] = useState("stripe");

  const [clientId, setClientId] = useState(null);
  const [freelancerId, setFreelancerId] = useState(null);
  const [jobId, setJobId] = useState(null);

  // Read timeline passed via navigation
  const passedTimeline = location.state?.timeline;

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      alert("Please login to access the payment page.");
      navigate("/login");
      return;
    }

    const user = JSON.parse(localStorage.getItem("user"));
    if (user?._id || user?.id) {
      setClientId(user._id || user.id);
    }

    // Prefer timeline object from navigation
    if (passedTimeline) {
      setFreelancerId(passedTimeline.applicant);
      setJobId(passedTimeline.jobId);
      setAmount(passedTimeline.totalAmount);
      localStorage.setItem("freelancerId", passedTimeline.applicant);
      localStorage.setItem("jobId", passedTimeline.jobId);
    } else {
      // fallback
      const storedJobId = localStorage.getItem("jobId");
      const storedFreelancerId = localStorage.getItem("freelancerId");
      if (storedJobId) setJobId(storedJobId);
      if (storedFreelancerId) setFreelancerId(storedFreelancerId);
    }
  }, [navigate, passedTimeline]);

  const connectWallet = async () => {
    if (!window.ethereum) return setError("MetaMask is not installed.");
    try {
      await window.ethereum.request({ method: "eth_requestAccounts" });
      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner();
      const address = await signer.getAddress();
      setClientWallet(address);
    } catch (err) {
      setError("Wallet connection failed.");
    }
  };

  const isValidObjectId = (id) => /^[0-9a-fA-F]{24}$/.test(id);

  const handlePayment = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(false);

    if (!amount || isNaN(amount) || amount <= 0) return setError("Invalid amount.");
    if (!currency || typeof currency !== "string") return setError("Invalid currency.");
    if (!["full", "escrow"].includes(type)) return setError("Invalid payment type.");
    if (!clientId || !freelancerId || !jobId) return setError("Missing required IDs.");

    if (![clientId, freelancerId, jobId].every(isValidObjectId)) {
      setError("Invalid ObjectId format.");
      setLoading(false);
      return;
    }

    const token = localStorage.getItem("token");
    if (!token) return setError("Authentication token missing.");

    const payload = {
      amount: parseFloat(amount),
      currency: currency.toLowerCase(),
      type,
      freelancerId,
      jobId,
    };

    try {
      if (method === "stripe") {
        if (!stripe || !elements) return setError("Stripe.js not loaded.");

        const res = await axios.post(`${API_BASE_URL}/create-payment`, payload, {
          headers: { Authorization: `Bearer ${token}` },
        });

        const clientSecret = res.data.clientSecret;
        if (!clientSecret) return setError("Missing Stripe clientSecret.");

        const result = await stripe.confirmCardPayment(clientSecret, {
          payment_method: { card: elements.getElement(CardElement) },
        });

        if (result.error) setError(result.error.message);
        else if (result.paymentIntent?.status === "succeeded") setSuccess(true);
        else setError("Payment did not succeed.");
      }

      if (method === "crypto") {
        if (!clientWallet) {
          await connectWallet();
          if (!clientWallet) return setError("Wallet not connected.");
        }

        const res = await axios.post(
          `${API_BASE_URL}/crypto-request`,
          {
            freelancerId,
            jobId,
            type,
            milestones: [{ title: "Single Payment", amountUSD: parseFloat(amount) }],
          },
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        const cryptoPayment = res.data?.payments?.[0];
        if (!cryptoPayment) return setError("No crypto payment data.");

        const provider = new ethers.BrowserProvider(window.ethereum);
        const signer = await provider.getSigner();

        const tx = await signer.sendTransaction({
          to: cryptoPayment.toWallet,
          value: ethers.parseEther(cryptoPayment.amountCrypto),
        });

        await axios.post(
          `${API_BASE_URL}/verify-crypto`,
          { intentId: cryptoPayment._id, txHash: tx.hash },
          { headers: { Authorization: `Bearer ${token}` } }
        );

        setSuccess(true);
      }
    } catch (err) {
      console.error("Payment Error:", err);
      setError(err?.response?.data?.error || "Payment failed.");
    }
    setLoading(false);
  };

  return (
    <form onSubmit={handlePayment} style={{ maxWidth: 400, margin: "auto", background: "#222", padding: 20, borderRadius: 8, color: "#fff" }}>
      <label>Amount</label>
      <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="Enter amount" style={{ width: "100%", padding: 8, marginBottom: 10 }} />

      <label>Currency</label>
      <input type="text" value={currency} onChange={(e) => setCurrency(e.target.value)} placeholder="e.g. usd" style={{ width: "100%", padding: 8, marginBottom: 10 }} />

      <label>Payment Type</label>
      <select value={type} onChange={(e) => setType(e.target.value)} style={{ width: "100%", padding: 8, marginBottom: 10 }}>
        <option value="full">Full Payment</option>
        <option value="escrow">Escrow</option>
      </select>

      <label>Payment Method</label>
      <select value={method} onChange={(e) => setMethod(e.target.value)} style={{ width: "100%", padding: 8, marginBottom: 20 }}>
        <option value="stripe">Card</option>
        <option value="crypto">Crypto</option>
      </select>

      {method === "crypto" && (
        <button type="button" onClick={connectWallet} style={{ background: "#444", color: "#fff", padding: 10, border: "1px solid #888", borderRadius: 5, marginBottom: 10, width: "100%" }}>
          {clientWallet ? `Connected: ${clientWallet.slice(0, 6)}...${clientWallet.slice(-4)}` : "🔌 Connect Wallet"}
        </button>
      )}

      {method === "stripe" && (
        <>
          <label>Card Details</label>
          <div style={{ padding: 10, background: "#333", borderRadius: 5, marginBottom: 15 }}>
            <CardElement options={cardStyle} />
          </div>
        </>
      )}

      {error && <p style={{ color: "red" }}>{error}</p>}
      {success && <p style={{ color: "green" }}>Payment successful!</p>}

      <button type="submit" disabled={loading} style={{ background: "purple", color: "#fff", padding: 10, border: "none", borderRadius: 5, width: "100%" }}>
        {loading ? "Processing..." : "Pay Now"}
      </button>
    </form>
  );
};

export default PaymentForm;
